package main

const workbenchHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DNS Failure Lab</title>
<style>
:root{font:16px system-ui,sans-serif;color:#17212b;background:#f4f6f8}*{box-sizing:border-box}body{margin:0}header{background:#122334;color:white;padding:24px max(24px,calc((100vw - 1100px)/2))}h1{margin:0 0 6px;font-size:28px}header p{margin:0;color:#bfd0dc}main{max-width:1100px;margin:24px auto;padding:0 20px;display:grid;gap:18px}.card{background:white;border:1px solid #dbe3e8;border-radius:10px;padding:20px;box-shadow:0 2px 8px #1232}h2{font-size:18px;margin:0 0 14px}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center}select,button{font:inherit;padding:9px 12px;border-radius:6px;border:1px solid #9daeb8;background:white}button{background:#0b637e;color:white;border-color:#0b637e;cursor:pointer}button:hover{background:#084e65}.badge{display:inline-block;border-radius:20px;padding:4px 10px;background:#e5f3e9;color:#175a34}.badge.alert{background:#fae9e9;color:#a32626}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:9px;border-bottom:1px solid #e7edf0;vertical-align:top}th{color:#52636c}code{font-size:13px}small{color:#5d6c76}.muted{color:#5d6c76}ul{padding-left:20px}@media(max-width:760px){.grid{grid-template-columns:1fr}table{display:block;overflow-x:auto}}
input{font:inherit;padding:9px 12px;border-radius:6px;border:1px solid #9daeb8;background:white}
</style></head><body><header><h1>DNS Failure Lab</h1><p>Synthetic DNS incidents, observable from query to upstream response</p></header><main>
<section class="card"><h2>Experiment controls</h2><div class="controls"><label for="scenario">Scenario</label><select id="scenario"><option value="healthy">Healthy</option><option value="slow">Slow resolution</option><option value="timeout">DNS timeout</option><option value="wrong_answer">Incorrect answer</option><option value="stale_answer">Stale cached answer</option><option value="bad_release">Bad release</option></select><button id="apply">Apply scenario</button><button id="probe">Run probe</button><button id="rollback">Rollback and verify</button><span id="message" class="muted"></span></div><p class="muted">All traffic is synthetic and stays inside this lab. A probe runs automatically every 5 seconds.</p></section>
<div class="grid"><section class="card"><h2>Current signal</h2><div id="signal" class="badge">Loading</div><p id="signalDetail"></p></section><section class="card"><h2>Incident brief · draft for review</h2><p id="summary" class="muted">No active alert.</p><p id="impact"></p><p id="review"></p><div id="evidence"></div></section></div>
<section class="card"><h2>Incident review</h2><p class="muted">Drafts are saved when a synthetic alert begins. Reviewer names are self-asserted; approval records a local decision and does not publish externally.</p><div class="controls"><input id="reviewer" aria-label="Reviewer name" placeholder="Reviewer name"><input id="reviewNote" aria-label="Review note" placeholder="Review note"><button id="approve">Approve latest draft</button><button id="reject">Reject latest draft</button><span id="reviewMessage" class="muted"></span></div><table><thead><tr><th>Incident</th><th>Status</th><th>Summary</th><th>Evidence</th><th>Reviewer</th></tr></thead><tbody id="incidents"></tbody></table></section>
<section class="card"><h2>Probe timeline</h2><table><thead><tr><th>Time</th><th>Event / trace</th><th>Release</th><th>Observed outcome</th><th>Diagnosis</th><th>DNS span</th><th>Authority check</th><th>HTTP span</th><th>Total</th></tr></thead><tbody id="timeline"></tbody></table></section>
<section class="card"><h2>Telemetry</h2><p>Structured probe logs are emitted as JSON. <a href="/metrics">Prometheus counters</a> and <a href="/api/state">JSON evidence</a> are available for inspection.</p></section>
</main><script>
const $ = id => document.getElementById(id);
async function call(path, body) { const response = await fetch(path, {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body||{})}); if(!response.ok) throw new Error(await response.text()); return response.json(); }
function cell(row,value){const td=document.createElement('td');td.textContent=value;row.appendChild(td)}
let currentDraft=null;
async function refreshIncidents(){const items=await (await fetch('/api/incidents')).json();currentDraft=items.find(item=>item.status==='draft')||null;const rows=$('incidents');rows.replaceChildren();for(const item of items.slice(0,10)){const tr=document.createElement('tr');[item.id,item.status,item.summary,item.evidence.join(', '),item.reviews.length?item.reviews[item.reviews.length-1].reviewer:'—'].forEach(v=>cell(tr,v));rows.appendChild(tr)}}
async function refresh(){try{const data=await (await fetch('/api/state')).json();const active=!!data.alert;$('signal').textContent=active?'Alert: '+data.alert.reason:'Healthy / no active alert';$('signal').className='badge'+(active?' alert':'');$('signalDetail').textContent=active?'Triggered by '+data.alert.event_id+' at '+new Date(data.alert.at).toLocaleString():'Latest synthetic probe passed, or no probe has run yet.';const b=data.brief;$('summary').textContent=b?b.summary:'No active alert.';$('impact').textContent=b?b.impact:'';$('review').textContent=b?b.review:'';$('evidence').textContent=b?'Evidence: '+b.evidence.join(', '):'';const rows=$('timeline');rows.replaceChildren();for(const e of data.events.slice().reverse().slice(0,30)){const tr=document.createElement('tr');const span=name=>{const s=e.spans.find(x=>x.name===name);return s?s.outcome+' · '+s.detail+' · '+s.duration_ms+' ms'+(s.ttl_remaining_ms?' · TTL '+s.ttl_remaining_ms+' ms':''):'—'};[new Date(e.at).toLocaleTimeString(),e.id,e.release,e.outcome,(e.diagnosis?e.diagnosis.class+' · '+e.diagnosis.confidence:'—'),span('dns.resolve'),span('dns.authoritative_check'),span('http.upstream'),e.total_ms+' ms'].forEach(v=>cell(tr,v));rows.appendChild(tr)}await refreshIncidents()}catch(err){$('message').textContent='Refresh failed: '+err.message}}
$('apply').onclick=async()=>{try{await call('/api/scenario',{scenario:$('scenario').value});$('message').textContent='Scenario applied. Run a probe or wait for the next scheduled probe.';await refresh()}catch(err){$('message').textContent=err.message}};
$('probe').onclick=async()=>{try{$('message').textContent='Running probe…';await call('/api/probe');$('message').textContent='Probe complete.';await refresh()}catch(err){$('message').textContent=err.message}};
$('rollback').onclick=async()=>{try{$('message').textContent='Rolling back and verifying…';const e=await call('/api/rollback');$('message').textContent='Rollback probe: '+e.outcome;await refresh()}catch(err){$('message').textContent=err.message}};
async function review(decision){try{if(!currentDraft)throw new Error('No draft to review');const reviewer=$('reviewer').value.trim();if(!reviewer)throw new Error('Enter reviewer name');const item=await call('/api/incidents/'+currentDraft.id+'/review',{reviewer,decision,note:$('reviewNote').value});$('reviewMessage').textContent=item.id+' '+item.status;await refreshIncidents()}catch(err){$('reviewMessage').textContent=err.message}}
$('approve').onclick=()=>review('approve');$('reject').onclick=()=>review('reject');
refresh();setInterval(refresh,2000);
</script></body></html>`
